INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','NSAIDs','easy','flashcard','What is the mechanism by which aspirin irreversibly inhibits platelet function?','["Aspirin irreversibly acetylates a serine residue on the active site of COX-1, permanently inactivating thromboxane A2 synthesis for the lifetime of the platelet (7-10 days)."]','A','Aspirin is the ONLY NSAID that irreversibly inhibits COX. All other NSAIDs are reversible inhibitors. The platelet inhibition lasts 7-10 days (platelet lifespan) since platelets cannot synthesise new COX-1.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','NSAIDs','easy','flashcard','Name three major adverse effects of non-selective NSAIDs related to their mechanism of COX inhibition.','["1. GI toxicity (ulceration, bleeding) \u2014 loss of PGI2/PGE2 gastroprotection; 2. Renal toxicity (reduced blood flow, sodium retention, AKI); 3. Cardiovascular risk (increased MI/stroke risk) \u2014 reduced PGI2."]','A','All NSAIDs carry boxed warnings for cardiovascular and GI risk. The GI and renal effects are due to COX-1 inhibition reducing prostaglandin-mediated tissue protection. Cardiovascular risk is particularly high with selective COX-2 inhibitors.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','NSAIDs','medium','flashcard','Why does celecoxib (selective COX-2 inhibitor) have a lower GI risk than non-selective NSAIDs, and why does it still carry cardiovascular risk?','["Lower GI risk: COX-1 (which mediates gastroprotection) is spared. Cardiovascular risk: COX-2-derived prostacyclin (PGI2) from endothelium is inhibited, creating a prothrombotic TXA2/PGI2 imbalance."]','A','Celecoxib is significantly more selective for COX-2 than COX-1, sparing the gastric cytoprotective effects of COX-1. However, by inhibiting COX-2-derived PGI2 (vasodilatory, antiaggregatory) while COX-1-mediated TXA2 remains intact, it promotes platelet aggregation and vasoconstriction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','NSAIDs','medium','flashcard','Which NSAID is considered the safest choice for a patient with established cardiovascular disease who requires anti-inflammatory therapy?','["Naproxen \u2014 considered the safest NSAID regarding cardiovascular risk due to its more balanced COX-1/COX-2 inhibition profile. Should be combined with a PPI if GI risk is present."]','A','All NSAIDs except aspirin carry boxed warnings for increased cardiovascular risk including MI and stroke. Naproxen is considered least cardiovascular-harmful among the non-selective NSAIDs. Celecoxib and ibuprofen should be avoided in established CVD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','NSAIDs','medium','flashcard','What is the clinical significance of the irreversibility of aspirin vs. reversibility of other NSAIDs for antiplatelet therapy?','["Aspirin''''s irreversible COX-1 inhibition means its antiplatelet effect lasts the full lifespan of platelets (7-10 days) with once-daily dosing. Other NSAIDs cause transient, reversible platelet inhibition proportional to drug plasma levels."]','A','This pharmacodynamic difference means only aspirin is used for long-term antiplatelet prophylaxis at 75-162 mg/day. Other NSAIDs can transiently interfere with aspirin''''s antiplatelet effect if taken within 2 hours before aspirin.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','NSAIDs','hard','flashcard','Why should NSAIDs be avoided in the third trimester of pregnancy?','["NSAIDs in the third trimester risk premature closure of the ductus arteriosus (normally kept open by PGE2) and can impair renal function in the fetus. Acetaminophen is preferred if analgesic/antipyretic therapy is needed."]','A','PGE1 (alprostadil) is used in neonates with congenital heart disease to KEEP the ductus arteriosus open. Conversely, COX inhibitors by reducing PGE synthesis promote premature ductal closure. NSAIDs may also cause oligohydramnios by reducing fetal renal prostaglandin synthesis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','NSAIDs','hard','flashcard','State the dose-dependent pharmacokinetics of aspirin and how this affects toxicity monitoring.','["At analgesic doses (<2 g/day): first-order kinetics, half-life ~3.5 hours. At anti-inflammatory doses (>4 g/day): zero-order (saturation) kinetics, half-life extends to 15+ hours \u2014 risk of salicylate accumulation and toxicity (salicylism: tinnitus, dizziness, hyperventilation)."]','A','The saturation of hepatic conjugation pathways at high doses converts the kinetics from first-order to zero-order. Tinnitus is an early warning sign of salicylism. Alkalinisation of urine (sodium bicarbonate) increases salicylate excretion and is used in toxicity management.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','NSAIDs','medium','flashcard','What is misoprostol, and when is it used in NSAID therapy?','["Misoprostol is a PGE1 analog that inhibits gastric acid secretion and stimulates mucus/bicarbonate production. It is used with NSAIDs in high-risk patients (previous ulcer, elderly, anticoagulant use) to prevent NSAID-induced gastric ulcers."]','A','Misoprostol replaces the gastroprotective prostaglandins lost by NSAID-induced COX inhibition. A fixed-dose combination product (diclofenac + misoprostol) is available. PPIs (omeprazole, pantoprazole) are the more commonly used gastroprotective agents with NSAIDs due to better tolerability.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','NSAIDs','easy','flashcard','What is the analgesic action of NSAIDs at the peripheral level?','["NSAIDs decrease synthesis of PGE2, which sensitises nociceptors to bradykinin, histamine, and other inflammatory mediators. By reducing PGE2, NSAIDs raise the pain threshold and reduce sensitisation of peripheral pain receptors."]','A','COX-2 is primarily responsible for the analgesic effect as it is expressed during inflammation and injury. The analgesic effect is peripheral (sensitisation) as well as central (hypothalamic thermoregulation). All NSAIDs have equivalent analgesic efficacy at equi-effective doses.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','NSAIDs','hard','flashcard','How does ibuprofen interact with aspirin''''s antiplatelet effect, and how should patients be counselled?','["Ibuprofen competes reversibly with aspirin at the COX-1 catalytic site. If taken within 2 hours BEFORE aspirin, ibuprofen blocks aspirin''''s access to the serine acetylation site, preventing permanent platelet inhibition. Patients should take immediate-release aspirin at least 60 minutes before or 8+ hours after ibuprofen."]','A','This interaction is clinically significant for patients taking low-dose aspirin for cardioprotection who also need anti-inflammatory therapy. Naproxen does not appear to have the same interaction. This is a pharmacokinetic competitive binding interaction at the enzyme active site.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Analgesics in MSK','easy','flashcard','Why does paracetamol (acetaminophen) lack significant anti-inflammatory activity compared to NSAIDs?','["Paracetamol is inactivated peripherally by peroxidases in inflamed tissues, so it primarily inhibits prostaglandin synthesis in the CNS (antipyretic/analgesic) but has weak peripheral effect (minimal anti-inflammatory activity). It does not affect platelet function."]','A','Paracetamol inhibits COX primarily in the CNS where there is no oxidative inactivation. In peripheral inflammatory sites, high concentrations of peroxides inactivate paracetamol''''s COX-inhibitory capacity. This explains why paracetamol is analgesic and antipyretic but not anti-inflammatory.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Analgesics in MSK','easy','flashcard','What is the toxic metabolite of paracetamol in overdose, and how does N-acetylcysteine work?','["NAPQI (N-acetyl-p-benzoquinoneimine) is the toxic reactive metabolite. In overdose, glutathione is depleted and NAPQI binds hepatic proteins causing necrosis. N-acetylcysteine replenishes glutathione stores, allowing NAPQI to be safely conjugated."]','A','At normal doses, NAPQI is detoxified by conjugation with glutathione. In overdose (>150 mg/kg or >7.5 g in adults), glutathione is depleted. N-acetylcysteine is most effective within 8-10 hours of overdose. Risk is higher in alcoholics and those with liver disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Analgesics in MSK','medium','flashcard','What are the three opioid receptor families, and what is the primary receptor mediating analgesia?','["Three families: mu (MOR), kappa (KOR), and delta (DOR). Analgesia is primarily mediated by mu receptors (modulate thermal, mechanical, chemical nociception). Kappa receptors in the dorsal horn also contribute. All are G-protein coupled receptors that inhibit adenylyl cyclase."]','A','Mu receptor activation produces: analgesia, euphoria, respiratory depression, constipation, miosis. Kappa receptor activation produces: analgesia, sedation, dysphoria. Delta receptors are mainly in the periphery. Understanding receptor selectivity helps explain adverse effect profiles of different opioids.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Analgesics in MSK','medium','flashcard','Why is meperidine contraindicated in patients with renal insufficiency and elderly patients?','["Meperidine is metabolised to normeperidine, a neurotoxic metabolite. In renal insufficiency, normeperidine accumulates, causing delirium, hyperreflexia, myoclonus, and seizures \u2014 effects NOT reversed by naloxone and potentially worsened by it. Duration of use should be limited to \u226448 hours."]','A','Normeperidine has a longer half-life than meperidine itself. Elderly patients also have reduced renal function. The anticholinergic effects of meperidine increase delirium risk. These factors make meperidine particularly dangerous in elderly patients with renal impairment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Analgesics in MSK','medium','flashcard','What is buprenorphine''''s receptor profile, and why does this make it suitable for opioid dependence treatment?','["Buprenorphine is a potent PARTIAL AGONIST at mu receptors and an ANTAGONIST at kappa receptors. Its high mu receptor affinity and partial agonism create a ceiling effect on respiratory depression and euphoria, lower abuse potential, and ability to block other opioids. It can be prescribed in office settings (unlike methadone for addiction)."]','A','Buprenorphine''''s high receptor affinity means it can displace full agonists, potentially precipitating withdrawal if given to opioid-dependent patients actively using full agonists. The ceiling effect means partial reversal with naloxone (requires higher doses). Available as sublingual, buccal, subdermal, transdermal, and parenteral formulations.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Analgesics in MSK','hard','flashcard','What is the unique pharmacological profile of methadone that distinguishes it from other opioids?','["Methadone is a mu agonist + NMDA receptor antagonist + norepinephrine and serotonin reuptake inhibitor. Its long variable half-life (12-150 hours) with shorter duration of analgesia (4-8 hours) risks accumulation and overdose. It can prolong QTc causing torsades de pointes. Complex CYP450 drug interactions."]','A','Methadone''''s NMDA antagonism makes it useful for neuropathic pain where other opioids fail. Its long half-life means dosage adjustments should only occur every 5-7 days to avoid accumulation. QTc prolongation warrants baseline and serial ECGs. It is used for chronic pain and opioid substitution therapy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Analgesics in MSK','easy','flashcard','Which opioid adverse effects do NOT develop tolerance with long-term use?','["Constipation and miosis (pupillary constriction) \u2014 tolerance does NOT significantly develop to these effects. Tolerance does develop to sedation, respiratory depression, euphoria, nausea, and analgesia."]','A','This is clinically important: patients on long-term opioids will always need bowel management (stimulant laxatives; peripherally acting mu receptor antagonists like methylnaltrexone or naloxegol for opioid-induced constipation). Pinpoint pupils also persist indefinitely.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Analgesics in MSK','medium','flashcard','What is the WHO analgesic ladder and how do NSAIDs and opioids relate to it in MSK pain management?','["Step 1: Non-opioid analgesics (paracetamol, NSAIDs) for mild pain. Step 2: Weak opioids \u00b1 non-opioids (codeine, tramadol) for mild-moderate pain. Step 3: Strong opioids \u00b1 non-opioids (morphine, oxycodone, fentanyl) for moderate-severe pain. NSAIDs have opioid-sparing effects at all steps."]','A','The WHO ladder was originally for cancer pain but is applied broadly to MSK pain. NSAIDs combined with opioids provide superior analgesia (additive/synergistic effect) and allow lower opioid doses (opioid-sparing effect), reducing opioid side effects. Adjuvant analgesics (tricyclics, gabapentinoids) are added for neuropathic components.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Analgesics in MSK','hard','flashcard','How does tramadol''''s mechanism of action differ from morphine, and what specific drug interactions carry a black box warning?','["Tramadol: mu agonist (weak) + norepinephrine and serotonin reuptake inhibitor. Unlike morphine (pure mu agonist), tramadol''''s serotonergic activity creates risk of SEROTONIN SYNDROME with SSRIs, SNRIs, MAOIs, and TCAs. Naloxone only partially reverses tramadol toxicity and may increase seizure risk."]','A','Tramadol has lower respiratory depression risk than morphine due to weaker mu agonism. However, the serotonergic component creates unique drug interaction risks not seen with pure opioids. Overdose can cause seizures. CYP2D6 converts tramadol to the active O-desmethyltramadol metabolite with higher mu receptor affinity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Analgesics in MSK','hard','flashcard','What is tapentadol''''s dual mechanism and which pain conditions is it specifically approved for?','["Tapentadol: mu opioid receptor AGONIST + norepinephrine reuptake INHIBITOR (NRI). Approved for moderate-to-severe acute and chronic pain, including neuropathic pain associated with diabetic peripheral neuropathy. The NRI component contributes specifically to neuropathic pain relief."]','A','Tapentadol does not inhibit serotonin reuptake (unlike tramadol), so it has less risk of serotonin syndrome. It is metabolised mainly by glucuronidation (not CYP450), so fewer drug interactions. It does not produce active metabolites, so dose adjustment is not needed in mild-moderate renal impairment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','DMARDs for RA','easy','flashcard','What is the mechanism of action of methotrexate in rheumatoid arthritis?','["Methotrexate is a folic acid antagonist that inhibits cytokine production and purine nucleotide biosynthesis, leading to immunosuppressive and anti-inflammatory effects. At RA doses (weekly low-dose), these immunomodulatory effects predominate rather than the anti-proliferative cancer mechanism."]','A','At RA doses, methotrexate is given once weekly (much lower than cancer doses), reducing adverse effects. Folate supplementation is given concurrently to reduce GI and hepatic adverse effects. Response occurs within 3-6 weeks. Monitoring: LFTs, CBC, signs of infection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','DMARDs for RA','medium','flashcard','Why is folic acid supplementation given alongside methotrexate in rheumatoid arthritis?','["Folic acid supplementation improves tolerability of methotrexate and reduces GI adverse effects (mouth ulcers, nausea) and hepatic adverse effects WITHOUT significantly compromising anti-inflammatory efficacy. Methotrexate depletes folate by inhibiting dihydrofolate reductase."]','A','Methotrexate inhibits dihydrofolate reductase (DHFR) and thymidylate synthase, depleting reduced folates. Many of the adverse effects (mucositis, megaloblastic changes) are folate-depletion related. However, the anti-inflammatory mechanism at RA doses is via adenosine release, which is NOT folate-dependent — hence efficacy is maintained.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','DMARDs for RA','medium','flashcard','List the key adverse effects that require monitoring during long-term methotrexate therapy.','["1. Hepatotoxicity (elevated LFTs, fibrosis, cirrhosis with long-term use). 2. Cytopenias \u2014 leukopenia, thrombocytopenia, pancytopenia. 3. Pulmonary toxicity \u2014 acute pneumonitis-like syndrome. 4. Mucosal ulceration and nausea. 5. Teratogenicity \u2014 absolutely contraindicated in pregnancy."]','A','Monitoring parameters: periodic LFTs, CBC, serum creatinine, and monitoring for signs of infection. Methotrexate causes immunosuppression. Avoid alcohol (increased hepatotoxicity). Contraindicated in renal impairment, hepatic disease, and pregnancy. Drug interactions: NSAIDs may increase methotrexate levels by competing for tubular secretion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','DMARDs for RA','easy','flashcard','What is the mechanism of action of hydroxychloroquine in rheumatoid arthritis?','["The mechanism of hydroxychloroquine in autoimmune disorders is UNKNOWN. It is an antimalarial that modulates the immune system by unknown mechanisms. Onset of effects takes 6 weeks to 6 months. It has less adverse effects on the liver and immune system than other DMARDs."]','A','Despite an unknown mechanism in RA, hydroxychloroquine is effective for mild RA and as part of triple DMARD therapy (methotrexate + sulfasalazine + hydroxychloroquine). Key adverse effect: irreversible retinal toxicity (maculopathy) requiring regular ophthalmological monitoring. Also used in SLE and malaria.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','DMARDs for RA','hard','flashcard','Describe the mechanism of leflunomide and the washout protocol required before pregnancy.','["Leflunomide is converted to an active metabolite (A77 1726) that reversibly inhibits dihydroorotate dehydrogenase (DHODH), blocking de novo pyrimidine synthesis in proliferating lymphocytes. Long half-life active metabolite can persist in plasma up to 2 years. Before pregnancy: cholestyramine washout (8 g TID x11 days) then verify plasma levels <0.02 mg/L on two occasions 14 days apart."]','A','Leflunomide is absolutely contraindicated in pregnancy. Without washout, the active metabolite can persist for up to 2 years due to enterohepatic recirculation. Cholestyramine binds the metabolite in the gut, interrupting enterohepatic circulation and accelerating elimination from 2 years to weeks.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','DMARDs for RA','medium','flashcard','When is sulfasalazine used in RA and what are its key adverse effects?','["Sulfasalazine is used in mild-moderate RA as monotherapy or in combination (triple therapy with methotrexate + hydroxychloroquine). Key adverse effects: GI (nausea, vomiting, anorexia), leukopenia, oligospermia (reversible), orange-yellow discolouration of urine/skin. Mechanism in RA is unknown. Onset 1-3 months."]','A','Sulfasalazine is split by gut bacteria into sulfapyridine (antibacterial) and 5-aminosalicylate (anti-inflammatory). Its mechanism in RA is distinct from its IBD mechanism. It is contraindicated in sulfonamide or aspirin allergy. GI adverse effects can be reduced by using enteric-coated formulation.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','DMARDs for RA','easy','flashcard','Which traditional DMARDs are absolutely contraindicated in pregnancy?','["Methotrexate (teratogenic and abortifacient) and leflunomide (teratogenic, with long-acting metabolite) are absolutely contraindicated in pregnancy. Both require effective contraception in women of childbearing potential."]','A','Hydroxychloroquine appears relatively safe in pregnancy (used in SLE). Sulfasalazine can be continued in pregnancy. When RA flares during pregnancy, low-dose prednisolone and hydroxychloroquine are generally preferred. Any adverse pregnancy outcomes should be reported to the relevant pregnancy registry.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','DMARDs for RA','medium','flashcard','What is the preferred first-line DMARD for newly diagnosed RA and what is the target of treatment?','["Methotrexate is generally preferred for monotherapy initiation in RA. Target of therapy is clinical remission (DAS28 <2.6) or low disease activity. Treatment should start as soon as possible after diagnosis. If inadequate response to methotrexate after 3-6 months, add another DMARD or biologic."]','A','The treat-to-target strategy aims for remission or low disease activity. Regular monitoring (every 1-3 months initially) with disease activity scores drives treatment escalation decisions. Early aggressive treatment prevents irreversible joint damage.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','DMARDs for RA','hard','flashcard','How do conventional DMARDs differ from biologic DMARDs in their mechanism and place in RA therapy?','["Conventional (traditional) DMARDs (methotrexate, hydroxychloroquine, leflunomide, sulfasalazine) are small molecules with broad immunomodulatory effects. Biologic DMARDs are large protein-based agents targeting specific inflammatory mediators (TNF-alpha, IL-6, CD20, CD28/CD80). Biologics are used after inadequate response to conventional DMARDs."]','A','Conventional DMARDs are oral and less expensive but have broader adverse effect profiles. Biologics are more targeted but require injection/infusion, are expensive, carry infection risk (TB reactivation, opportunistic infections), and require TB screening. Tofacitinib is a JAK inhibitor — a targeted synthetic DMARD bridging these two categories.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','DMARDs for RA','medium','flashcard','What is tofacitinib and how does it differ from biologic DMARDs in RA?','["Tofacitinib is an oral Janus kinase (JAK) inhibitor \u2014 a targeted synthetic DMARD. It inhibits JAK1, JAK3 (and to lesser extent JAK2), blocking intracellular signalling downstream of inflammatory cytokine receptors. Unlike biologics (large protein molecules given by injection/infusion), tofacitinib is a small molecule taken orally twice daily."]','A','Tofacitinib is used for moderate-to-severe established RA after inadequate response or intolerance to methotrexate. It is metabolised primarily by CYP3A4. Key monitoring: haemoglobin (avoid if <9 g/dL), lymphocyte and neutrophil counts, infection risk. Long-term safety concerns (malignancy risk) mean it is usually reserved for patients failing other agents.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Biologic Therapies','easy','flashcard','What are the TNF-alpha inhibitors used in rheumatoid arthritis, and what is their common mechanism?','["TNF-alpha inhibitors: adalimumab, certolizumab, etanercept, golimumab, infliximab. Common mechanism: they bind to TNF-alpha (or its receptors) blocking its interaction with cell surface receptors. This inhibits the downstream inflammatory cascade (collagenase production, cartilage degradation, bone resorption)."]','A','TNF-alpha and IL-1 are key proinflammatory cytokines secreted by synovial macrophages in RA. TNF-alpha inhibitors can show clinical response within 2 weeks. They are used after inadequate response to conventional DMARDs. All can be combined with methotrexate for enhanced efficacy (etanercept + MTX combination is particularly well-studied).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Biologic Therapies','medium','flashcard','How does abatacept prevent T-cell activation in rheumatoid arthritis?','["T-cell activation requires two signals: 1) antigen-MHC complex binding to TCR; 2) CD80/CD86 on APC binding to CD28 on T-cell (costimulation). Abatacept is a fusion protein (CTLA-4-Ig) that competes with CD28 for binding to CD80/CD86, blocking costimulation and preventing full T-cell activation."]','A','Without the CD28-CD80/CD86 costimulatory signal, T-cells become anergic (tolerant) rather than activated. Abatacept is given IV every 4 weeks or subcutaneously weekly. Common adverse effects include infusion reactions, upper respiratory infections, headache, and nausea.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Biologic Therapies','easy','flashcard','Why must all patients be screened for tuberculosis before starting biologic DMARD therapy?','["Biologic DMARDs (especially TNF-alpha inhibitors) cause significant immunosuppression. Latent TB can reactivate during biologic therapy, leading to disseminated (miliary) TB. TB screening (tuberculin skin test or IGRA blood test) must be done before starting any biologic. Latent TB requires treatment (e.g., isoniazid) before or concurrent with biologic initiation."]','A','TNF-alpha is critical for granuloma formation and maintenance — the mechanism by which the immune system contains latent TB. Blocking TNF-alpha disrupts granuloma integrity, allowing Mycobacterium tuberculosis to disseminate. Other opportunistic infections (fungal, PCP) also risk with biologics.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Biologic Therapies','medium','flashcard','How does rituximab work in rheumatoid arthritis, and what premedication is required?','["Rituximab is a chimeric anti-CD20 monoclonal antibody directed against CD20 on B lymphocytes, causing B-cell depletion. In RA, B-cells perpetuate inflammation by activating T-cells, producing autoantibodies/rheumatoid factor, and producing proinflammatory cytokines. Premedication: methylprednisolone + acetaminophen + antihistamine to reduce infusion reactions. Given IV every 16-24 weeks."]','A','Rituximab is preferred in RA patients who have had lymphoma or who are hepatitis B surface antigen positive (anti-TNF agents are associated with HBV reactivation). It causes profound B-cell depletion lasting 6-9 months. Infusion reactions (urticaria, hypotension, angioedema) are most common during the first infusion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Biologic Therapies','hard','flashcard','What are the differences between infliximab and adalimumab as TNF-alpha inhibitors?','["Infliximab: chimeric (murine+human) monoclonal antibody, given IV every 8 weeks, MUST be combined with methotrexate (monotherapy causes anti-drug antibody formation reducing efficacy), approved for multiple conditions. Adalimumab: fully human recombinant monoclonal antibody, given SC weekly or every 2 weeks, can be used as monotherapy or with methotrexate."]','A','The chimeric nature of infliximab increases immunogenicity (anti-infliximab antibody formation) — hence mandatory methotrexate co-prescription to reduce antibody formation. Adalimumab being fully human has lower immunogenicity. Etanercept is a fusion protein (soluble TNF receptor + IgG Fc), structurally different from monoclonal antibodies.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Biologic Therapies','medium','flashcard','Name the non-TNF biologic agents used in RA and their targets.','["1. Abatacept \u2014 T-cell costimulation (CD80/CD86 blockade); 2. Rituximab \u2014 anti-CD20 (B-cell depletion); 3. Tocilizumab \u2014 IL-6 receptor antagonist; 4. Sarilumab \u2014 IL-6 receptor antagonist. Used after inadequate response to conventional DMARDs, or when TNF inhibitors have failed."]','A','Non-TNF biologics and TNF inhibitors should NEVER be combined (risk of severe infections). If a patient fails one TNF inhibitor, they can try: another TNF inhibitor, a non-TNF biologic, or add a conventional DMARD. Non-TNF biologics may also be preferred in specific situations (e.g., rituximab if prior lymphoma or HBsAg positive).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Biologic Therapies','easy','flashcard','What infections require hepatitis B screening before biologic DMARD therapy?','["Hepatitis B screening is required before biologic DMARD therapy because reactivation of hepatitis B virus (HBV) may occur with use of any biologic DMARD (particularly anti-TNF agents and rituximab). HBsAg-positive patients need antiviral prophylaxis with entecavir or tenofovir before and during biologic therapy."]','A','HBV reactivation can cause fulminant hepatitis and be fatal. Rituximab is particularly associated with HBV reactivation due to B-cell depletion (B-cells are important for controlling HBV). All patients should be screened for both HBsAg and anti-HBc before starting any biologic. TB and HBV screening are the two mandatory pre-biologic screenings.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Biologic Therapies','hard','flashcard','Tocilizumab blocks IL-6 receptors. What metabolic adverse effects are specifically associated with IL-6 inhibition?','["IL-6 receptor inhibition by tocilizumab is associated with: elevated liver enzymes (hepatotoxicity), hyperlipidaemia (increased LDL, HDL, triglycerides), neutropenia, hypertension, and increased infection risk. IL-6 is involved in acute phase protein regulation \u2014 its inhibition affects CRP, fibrinogen, and hepcidin (may improve anaemia of chronic disease)."]','A','IL-6 inhibits lipoprotein lipase, so blocking IL-6 increases lipid levels. This requires monitoring lipid profiles during tocilizumab therapy. The neutropenia typically does not increase infection risk at mild levels but requires monitoring. GI perforations have been reported, particularly in patients with diverticulitis.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Biologic Therapies','medium','flashcard','What is the mechanism of action of certolizumab and how does it differ from other anti-TNF agents?','["Certolizumab is a humanised antibody Fab'''' fragment conjugated to polyethylene glycol (PEGylated). It neutralises biological actions of TNF-alpha. Unlike other anti-TNF antibodies, certolizumab lacks an Fc region, meaning it does NOT cross the placenta via FcRn-mediated transport \u2014 potentially making it safer in pregnancy."]','A','The PEGylation extends its half-life. Given subcutaneously every 2 weeks. Adverse effects are similar to other TNF-alpha inhibitors. Its lack of an Fc region also means it does not fix complement or mediate ADCC (antibody-dependent cell-mediated cytotoxicity). It is available for RA, PsA, ankylosing spondylitis, and Crohn''''s disease.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Biologic Therapies','easy','flashcard','Which biologic DMARD specifically targets the IL-6 receptor and is used for RA when TNF inhibitors have failed?','["Tocilizumab and sarilumab both target the IL-6 receptor. They are recombinant monoclonal antibodies inhibiting IL-6 activity. They are administered subcutaneously every 2 weeks; tocilizumab can also be given IV every 4 weeks."]','A','IL-6 is a key proinflammatory cytokine in RA driving synovial inflammation, acute phase response (CRP, ESR elevation), anaemia of chronic disease, and fatigue. Blocking IL-6 receptor reduces these downstream effects. Tocilizumab was also used in severe COVID-19 for cytokine storm syndrome.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Corticosteroids in MSK','easy','flashcard','What are the main anti-inflammatory mechanisms of glucocorticoids relevant to MSK conditions?','["1. Inhibit phospholipase A2 (via annexin-1/lipocortin) \u2014 reducing arachidonic acid availability and prostaglandin/leukotriene synthesis. 2. Suppress gene expression of inflammatory cytokines (IL-1, IL-2, TNF-alpha, IL-6). 3. Inhibit COX-2 expression. 4. Reduce vascular permeability and leukocyte migration. 5. Suppress T-lymphocyte function."]','A','Glucocorticoids have the broadest anti-inflammatory effects of any drug class. Their rapid onset (hours) makes them useful as bridging therapy in RA while DMARDs reach effective levels. In gout, intra-articular steroids or oral prednisolone rapidly resolve acute attacks.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Corticosteroids in MSK','easy','flashcard','What is the most important complication requiring patient counselling before starting long-term corticosteroid therapy?','["Osteoporosis \u2014 glucocorticoids suppress intestinal calcium absorption, inhibit osteoblast activity (bone formation), and reduce sex hormone synthesis. Prednisone \u22655 mg/day for \u22653 months is a significant risk factor. All patients should receive calcium (1000-1200 mg/day) + vitamin D (800-1000 IU/day) and consider bisphosphonates."]','A','Glucocorticoid-induced osteoporosis (GIOP) is the most common iatrogenic osteoporosis. Vertebral fractures can occur even at low doses and early in therapy. Bisphosphonates (alendronate, risedronate, zoledronic acid) are used for prevention and treatment of GIOP. Trabecular bone is lost faster than cortical bone with steroids.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Corticosteroids in MSK','medium','flashcard','Why must corticosteroids be tapered rather than abruptly discontinued after long-term use?','["Long-term corticosteroid use suppresses the hypothalamic-pituitary-adrenal (HPA) axis. Abrupt discontinuation causes acute adrenal insufficiency \u2014 a potentially fatal condition with hypotension, hyponatraemia, hypoglycaemia, and cardiovascular collapse. The dose must be tapered slowly to allow recovery of endogenous cortisol production."]','A','HPA axis suppression occurs reliably with doses >5-7.5 mg prednisolone/day for >2-3 weeks. The adrenal cortex atrophies from prolonged ACTH suppression. Tapering schedules vary based on duration and dose of therapy. During physiological stress (infection, surgery), additional steroid coverage (''''sick day rules'''') is needed.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Corticosteroids in MSK','hard','flashcard','List six major adverse effects of long-term systemic corticosteroid therapy with their mechanisms.','["1. Osteoporosis \u2014 inhibit Ca2+ absorption, osteoblasts, sex hormones. 2. Hyperglycaemia \u2014 gluconeogenesis stimulation, insulin resistance. 3. Cushing syndrome \u2014 fat redistribution, moon face, buffalo hump. 4. Immunosuppression \u2014 lymphocyte suppression, infection risk. 5. Cataracts/glaucoma \u2014 aqueous humour effects. 6. Growth suppression in children \u2014 epiphyseal plate inhibition."]','A','Additional adverse effects include: hypertension (mineralocorticoid effects), hypokalaemia, peptic ulcer disease, psychiatric effects (euphoria, psychosis, depression), skin atrophy, wound healing impairment, adrenal suppression, and avascular necrosis of femoral head (high doses). The probability of adverse effects correlates with daily dose (Figure 26.7 in Lippincott).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Corticosteroids in MSK','medium','flashcard','What are the indications for intra-articular corticosteroid injection in musculoskeletal conditions?','["Indications: 1. Acute gout (1-2 joints affected, oral therapy contraindicated); 2. Osteoarthritis (single joint, inadequate response to analgesics); 3. RA (bridging or local joint control); 4. Shoulder/bursa injections for impingement syndrome, bursitis; 5. Trigger point injections for tendinopathy. Limits systemic exposure with local effect."]','A','Intra-articular injections should not be given more than 3-4 times per year in any one joint (risk of cartilage damage with repeated injections). Common preparations include methylprednisolone acetate, triamcinolone acetonide, and betamethasone. Septic arthritis must be excluded before injection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Corticosteroids in MSK','medium','flashcard','How do glucocorticoids cause hyperglycaemia, and how should this be managed in diabetic patients on corticosteroids?','["Glucocorticoids stimulate hepatic gluconeogenesis, decrease peripheral glucose uptake (anti-insulin effect), and increase glucagon secretion. This causes insulin resistance and hyperglycaemia (''''steroid diabetes''''). Diabetic patients should monitor blood glucose more frequently and adjust insulin/oral hypoglycaemic agents when starting or changing corticosteroid doses."]','A','Corticosteroid-induced hyperglycaemia typically peaks in the afternoon (corresponding to peak corticosteroid effect). Patients on morning prednisolone have their highest glucose readings 4-8 hours post-dose. Short-acting insulin coverage or increased morning insulin doses target this pattern. New-onset ''''steroid diabetes'''' may require temporary insulin therapy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Corticosteroids in MSK','hard','flashcard','What is the difference between physiological and pharmacological dosing of glucocorticoids, and what are the consequences of each?','["Physiological dose (replacement): 5-7.5 mg/day prednisolone equivalent \u2014 replaces endogenous cortisol (in adrenal insufficiency). Pharmacological dose (supraphysiological): >7.5 mg/day prednisolone \u2014 exploits anti-inflammatory effects exceeding physiological cortisol function. Pharmacological doses inevitably suppress HPA axis and cause Cushingoid adverse effects."]','A','The adrenal gland produces 5-10 mg cortisol/day equivalent in health. Any dose above this suppresses the HPA axis. High pharmacological doses (40-80 mg/day prednisolone for severe inflammation) achieve powerful anti-inflammatory effect but with proportionally greater adverse effect burden.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Corticosteroids in MSK','easy','flashcard','Which corticosteroid is commonly used for fetal lung maturation in preterm labour, and why?','["Betamethasone (and dexamethasone) \u2014 given to mother 24-48 hours before anticipated preterm delivery. These corticosteroids have high glucocorticoid activity and are NOT inactivated by placental 11-beta-hydroxysteroid dehydrogenase (11\u03b2-HSD2), allowing effective transplacental transfer to stimulate surfactant production in fetal lungs."]','A','Fetal lung maturation requires surfactant synthesis (which begins around 24-28 weeks). Glucocorticoids accelerate maturation by inducing surfactant proteins and enzymes. Prednisone is inactivated by placental 11β-HSD2 to inactive prednisone, so it does NOT effectively reach the fetus.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Corticosteroids in MSK','medium','flashcard','What is glucocorticoid-induced osteonecrosis (avascular necrosis), and which joint is most commonly affected?','["Glucocorticoid-induced osteonecrosis (avascular necrosis/AVN) results from disruption of blood supply to bone (impaired vascular supply, fat embolism, increased intraosseous pressure). The femoral head is most commonly affected. Risk increases with dose and duration \u2014 high-dose systemic steroids (>40 mg prednisolone/day) carry highest risk."]','A','AVN can also occur at the humeral head, knee condyles, and talus. Symptoms: progressive hip or shoulder pain, pain at rest, limited range of motion. Diagnosis: MRI is the gold standard (bone scan less sensitive). Early stages may respond to conservative management; advanced stages require joint replacement surgery.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Corticosteroids in MSK','hard','flashcard','Glucocorticoids inhibit expression of COX-2 and phospholipase A2. How does this compare mechanistically with NSAIDs?','["Glucocorticoids: act at transcriptional level, suppressing COX-2 gene expression (via glucocorticoid receptor-mediated transrepression of NF-\u03baB) AND inducing annexin-1/lipocortin which inhibits phospholipase A2 \u2014 preventing arachidonic acid release from membrane phospholipids. NSAIDs: act post-translationally, directly inhibiting already-formed COX enzymes. Glucocorticoids therefore act ''''upstream'''' of NSAIDs."]','A','This ''''upstream'''' mechanism means glucocorticoids suppress not just prostaglandin synthesis but also leukotriene synthesis (by reducing arachidonic acid availability) — unlike NSAIDs which only inhibit the cyclooxygenase pathway. Glucocorticoids also suppress the entire inflammatory gene programme beyond eicosanoids.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Gout Pharmacotherapy','easy','flashcard','What is the underlying metabolic disturbance in gout, and what are the main therapeutic targets?','["Gout is caused by hyperuricaemia \u2014 excess uric acid from overproduction and/or underexcretion. Crystals of monosodium urate deposit in joints and tissues. Therapeutic targets: 1. Reduce uric acid synthesis (xanthine oxidase inhibitors: allopurinol, febuxostat); 2. Increase uric acid excretion (uricosurics: probenecid); 3. Reduce crystal-induced inflammation (colchicine, NSAIDs, corticosteroids)."]','A','Target serum urate level is <6 mg/dL (below saturation point). Most patients with gout are under-excreters (90%) rather than over-producers. Diet (low purine, low alcohol, low fructose) is adjunctive but rarely sufficient alone. Diuretics (thiazides, loop diuretics) increase serum uric acid and should be minimised in gout patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Gout Pharmacotherapy','easy','flashcard','What is the mechanism of action of colchicine in acute gout and why is it neither an analgesic nor a uricosuric agent?','["Colchicine binds to tubulin causing microtubule depolymerisation. This disrupts neutrophil migration into the inflamed joint, blocking the inflammatory cascade. It is NOT a uricosuric (does not affect uric acid excretion) and NOT an analgesic (no opioid or COX inhibition). Its anti-inflammatory action is specific to crystal-induced inflammation."]','A','Colchicine must be given within 36 hours of attack onset for maximum efficacy. It alleviates gout-specific pain within 12 hours, but the pain relief is from anti-inflammatory action (neutrophil inhibition), not analgesic effect. The mechanism of inhibiting neutrophil chemotaxis is unique and different from all other anti-inflammatory agents.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Gout Pharmacotherapy','medium','flashcard','Allopurinol inhibits xanthine oxidase. What is the role of its active metabolite oxypurinol (alloxanthine)?','["Allopurinol is a substrate for xanthine oxidase, which converts it to oxypurinol (alloxanthine). Oxypurinol is ALSO a potent xanthine oxidase inhibitor with a half-life of 15-18 hours. This active metabolite explains why effective xanthine oxidase inhibition is maintained with once-daily dosing of allopurinol, even though allopurinol itself has a shorter half-life."]','A','Oxypurinol is renally excreted, so dose adjustment of allopurinol is required in patients with renal impairment (risk of oxypurinol accumulation and hypersensitivity syndrome). Allopurinol hypersensitivity syndrome (AHS) is more common in patients with reduced renal function. HLA-B*5801 screening identifies those at highest risk of severe reactions.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Gout Pharmacotherapy','medium','flashcard','What are the indications for prophylactic anti-inflammatory therapy when starting urate-lowering treatment?','["Prophylactic therapy (low-dose colchicine, NSAIDs, or corticosteroids) should be started with urate-lowering therapy and continued for AT LEAST 6 MONTHS. Indication: ALL patients starting urate-lowering therapy. Reason: Rapid changes in serum urate mobilise crystals from existing deposits, precipitating acute gout attacks during the initiation phase."]','A','This prophylaxis requirement is a key clinical pearl — patients often wrongly believe their gout is worsening on allopurinol. The first 6 months of urate-lowering therapy carry the highest risk of acute attacks due to urate crystal mobilisation. After 6 months, ongoing attacks become less frequent as crystal burden reduces.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Gout Pharmacotherapy','hard','flashcard','Compare allopurinol and probenecid — when would each be preferred for chronic gout management?','["Allopurinol: preferred for over-producers and under-excreters, safe if CrCl >10 mL/min (adjust dose), first-line in most patients. Probenecid: preferred for pure under-excreters with preserved renal function (CrCl >50 mL/min), avoided in nephrolithiasis (increases urinary uric acid). Allopurinol should be avoided with azathioprine (blocks azathioprine metabolism \u2014 lethal interaction \u2014 reduce azathioprine dose by 75%)."]','A','The allopurinol-azathioprine interaction is clinically critical: azathioprine is metabolised by xanthine oxidase to inactive metabolites; allopurinol blocks this, causing azathioprine accumulation and severe myelosuppression. Both drugs must not be co-prescribed at standard doses. This interaction also applies to mercaptopurine.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Gout Pharmacotherapy','easy','flashcard','What are the three drug classes effective for treating acute gout attacks?','["1. NSAIDs (e.g., indomethacin, naproxen) \u2014 first-line for most patients; avoid in renal impairment/peptic ulcer. 2. Colchicine \u2014 effective if given within 36 hours; avoid in severe renal/hepatic impairment. 3. Corticosteroids (oral prednisolone or intra-articular injection) \u2014 especially useful if NSAIDs and colchicine are contraindicated or poorly tolerated."]','A','Urate-lowering therapy (allopurinol, febuxostat, probenecid) should NOT be started during an acute attack and should not be stopped if already prescribed (changing serum urate precipitates attacks). All three acute gout therapies are anti-inflammatory, not urate-lowering.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Gout Pharmacotherapy','medium','flashcard','What is the mechanism and key adverse effect of probenecid in gout management?','["Probenecid inhibits the urate-anion exchanger (URAT1) in the proximal tubule, blocking uric acid reabsorption and increasing its urinary excretion (uricosuric effect). Key adverse effects: nausea, vomiting, dermatological reactions, rarely anaphylaxis. Contraindicated if CrCl <50 mL/min. Requires high fluid intake to prevent urolithiasis (increases urinary uric acid). Avoid with aspirin (competition for URAT1)."]','A','Probenecid also inhibits tubular secretion of other drugs (e.g., penicillins, cephalosporins) — historically used to prolong penicillin levels. Low-dose aspirin also inhibits URAT1 and can negate the uricosuric effect of probenecid, hence avoid concurrent use.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Gout Pharmacotherapy','hard','flashcard','A patient with severe tophaceous gout has failed allopurinol and febuxostat. What third-line option is available, and what serious adverse reactions require specific premedication?','["Pegloticase (recombinant uricase/urate oxidase) is the third-line option. It converts uric acid to allantoin (water-soluble, non-toxic, renally excreted). IV infusion every 2 weeks. Serious adverse reactions: infusion reactions and anaphylaxis \u2014 patients MUST be premedicated with antihistamines AND corticosteroids before each infusion. Pegloticase is indicated for patients who fail standard therapies."]','A','Pegloticase dramatically lowers serum urate (<1 mg/dL). However, approximately half of patients develop anti-pegloticase antibodies which cause loss of efficacy (serum urate rises back) AND increase infusion reaction risk. Monitoring serum urate before each infusion: if urate rises above 6 mg/dL, discontinue pegloticase (high infusion reaction risk if antibodies present).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Gout Pharmacotherapy','medium','flashcard','Why should aspirin (even low-dose) be avoided in gout if possible?','["Low-dose aspirin (75-162 mg/day) inhibits URAT1 in the proximal tubule at low doses, causing URATE RETENTION (reduces uric acid excretion) \u2014 paradoxically worsening hyperuricaemia. At high doses (>3 g/day), aspirin has uricosuric effects, but this is rarely used clinically. If aspirin is essential for cardioprotection, do not discontinue it \u2014 manage gout with allopurinol."]','A','This is the opposite of the high-dose uricosuric effect. Low-dose aspirin and probenecid should not be co-prescribed as aspirin competes with probenecid at URAT1, negating the uricosuric effect. Uricosuric agents (probenecid) lose efficacy with concurrent aspirin use.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Gout Pharmacotherapy','easy','flashcard','What adverse effects may occur with chronic colchicine use beyond GI effects?','["Chronic colchicine adverse effects: myopathy (muscle weakness, elevated CK), neutropenia, aplastic anaemia, and alopecia. These reflect the drug''''s mechanism (microtubule disruption) affecting not just neutrophil migration but also muscle cell function and haematopoietic cell division. Drug interactions: CYP3A4 and P-gp inhibitors (clarithromycin, itraconazole, verapamil) increase colchicine levels \u2014 dose reduction required."]','A','Acute GI adverse effects (nausea, vomiting, diarrhoea) are the most common — these are dose-limiting in the acute setting. Chronic myopathy occurs at lower doses and can be missed unless CK is measured. Concomitant statin use plus colchicine significantly increases myopathy risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Osteoporosis Pharmacotherapy','easy','flashcard','What is the mechanism of action of bisphosphonates in osteoporosis?','["Bisphosphonates bind to hydroxyapatite crystals in bone (particularly at sites of active remodelling) and decrease osteoclastic bone resorption. They are incorporated into bone matrix and when osteoclasts resorb bisphosphonate-containing bone, the bisphosphonate is released inside the osteoclast, inhibiting farnesyl pyrophosphate synthase (a key enzyme in the mevalonate pathway) and causing osteoclast apoptosis."]','A','Bisphosphonates inhibit the mevalonate pathway in osteoclasts, preventing prenylation of GTPases essential for osteoclast function and survival. The beneficial effects of alendronate persist for several years but discontinuation results in gradual loss of effect. Nitrogen-containing bisphosphonates (alendronate, risedronate, zoledronic acid) are much more potent than non-nitrogen-containing ones.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Osteoporosis Pharmacotherapy','medium','flashcard','What are the administration instructions for oral bisphosphonates and why are they important?','["Oral bisphosphonates: take on empty stomach with a FULL GLASS OF PLAIN WATER ONLY; no food/drink/other medications for 30-60 minutes (30 min for alendronate/risedronate, 60 min for ibandronate); remain UPRIGHT for 30-60 minutes after taking to prevent esophageal transit delay and reduce esophagitis/ulcer risk. Absorption is <1% and severely impaired by food."]','A','The risk of esophageal adverse effects (esophagitis, esophageal ulcers) necessitates these strict administration instructions. Calcium (including calcium-containing antacids) and other medications significantly reduce bisphosphonate absorption by chelation. Administration instructions are a frequent exam topic and patient counselling requirement.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Osteoporosis Pharmacotherapy','easy','flashcard','What is the mechanism of denosumab and how does it differ from bisphosphonates?','["Denosumab: monoclonal antibody targeting RANKL (receptor activator of nuclear factor kappa-B ligand), preventing RANKL from binding to RANK on osteoclast precursors \u2014 inhibiting osteoclast formation, function, and survival. Bisphosphonates: bind to hydroxyapatite in bone then are released inside osteoclasts to inhibit farnesyl pyrophosphate synthase."]','A','Key clinical difference: Denosumab''''s effects are reversible — discontinuation leads to rapid rebound increase in bone turnover (''''rebound phenomenon'''') and possible vertebral fractures. Unlike bisphosphonates which remain in bone for years after stopping. Given SC every 6 months. Adverse effects: infections, dermatological reactions, hypocalcaemia, rarely ONJ and atypical fractures.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Osteoporosis Pharmacotherapy','medium','flashcard','What are the two anabolic agents for osteoporosis and how do they differ from antiresorptive agents?','["1. Teriparatide (recombinant PTH 1-34): daily SC injection, stimulates osteoblasts to form new bone. 2. Abaloparatide (PTH-related peptide analog): daily SC injection, also anabolic. Both limited to 2 years maximum (osteosarcoma risk in rat studies). In contrast, antiresorptive agents (bisphosphonates, denosumab, raloxifene) reduce osteoclast-mediated bone resorption."]','A','Anabolic agents actually BUILD new bone, achieving greater gains in bone density than antiresorptive agents alone. They are reserved for patients at very high fracture risk or who have failed antiresorptive therapy. After completing anabolic therapy, transition to antiresorptive agent is needed to maintain bone density gains.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Osteoporosis Pharmacotherapy','hard','flashcard','What is the rationale for a ''''drug holiday'''' from bisphosphonates after 5 years of oral therapy or 3 years of IV zoledronic acid?','["With long-term bisphosphonate use (>5 years oral, >3 years IV), there is increasing risk of atypical femur fractures (subtrochanteric) and ONJ. Bisphosphonates become incorporated into bone mineral and continue to exert effects for years after cessation (residual effect). A drug holiday of 1-3 years allows this residual effect to persist while reducing the risk of atypical fractures. Restart if T-score worsens or fracture occurs."]','A','The drug holiday concept is based on bisphosphonates remaining biologically active in bone long after cessation — unlike most drugs. The decision to take a holiday should be individualised based on fracture risk (T-score, prior fractures, FRAX score). High-risk patients (T-score <-2.5, prior vertebral fracture) should generally not take a holiday.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Osteoporosis Pharmacotherapy','medium','flashcard','What are the effects of raloxifene on bone, breast cancer, and cardiovascular risk?','["Bone: estrogen agonist \u2014 maintains bone density, reduces vertebral fracture risk. Breast: estrogen antagonist \u2014 reduces invasive breast cancer risk by 50%. Endometrium: estrogen antagonist \u2014 does NOT increase endometrial cancer risk (unlike HRT). Cardiovascular: INCREASED risk of venous thromboembolism (DVT, PE) and stroke. Does NOT reduce non-vertebral or hip fractures (unlike bisphosphonates)."]','A','Raloxifene''''s SERM profile makes it useful for postmenopausal women at risk of breast cancer who also need osteoporosis prevention. However, it is less effective than bisphosphonates for fracture prevention (no hip fracture reduction). Adverse effects: hot flashes, leg cramps, VTE (contraindicated in women with VTE history).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Osteoporosis Pharmacotherapy','easy','flashcard','What is the role of calcium and vitamin D in osteoporosis management?','["Calcium: structural component of hydroxyapatite in bone; 1000-1200 mg/day elemental calcium recommended (from diet + supplements). Vitamin D: essential for calcium absorption in the gut; 800-1000 IU/day (D3 preferred). Both are BASELINE requirements for ALL osteoporosis treatments \u2014 inadequate calcium/vitamin D undermines any pharmacological osteoporosis therapy."]','A','Calcium carbonate (40% elemental Ca, taken with food for absorption) vs calcium citrate (21% elemental Ca, taken with or without food, preferred in achlorhydria/PPI users). Calcium can interfere with absorption of iron, thyroid hormone, fluoroquinolones, and tetracyclines. Older adults commonly have vitamin D deficiency.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Osteoporosis Pharmacotherapy','hard','flashcard','What is osteonecrosis of the jaw (ONJ) associated with bisphosphonate use, and what factors increase risk?','["ONJ: exposed, necrotic bone in the jaw persisting >8 weeks, occurring in bisphosphonate-treated patients. Pathophysiology: bisphosphonates impair osteoclast-mediated bone remodelling, disrupting the healing response to jaw trauma. Risk factors: IV bisphosphonate therapy (cancer patients receive higher doses), dental extractions/invasive dental procedures, poor oral hygiene, corticosteroid use, diabetes, smoking."]','A','ONJ risk is much higher with IV bisphosphonates in cancer patients (0.7-6.7%) than with oral bisphosphonates for osteoporosis (0.01-0.04%). Prevention: complete dental work before starting bisphosphonates; maintain good oral hygiene; discuss non-invasive dental management where possible during bisphosphonate therapy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Osteoporosis Pharmacotherapy','medium','flashcard','Which pharmacological classes of drugs can contribute to bone loss and increase fracture risk?','["1. Glucocorticoids \u2014 suppress osteoblasts, reduce calcium absorption (most common iatrogenic cause). 2. PPIs \u2014 reduce calcium absorption. 3. Loop diuretics \u2014 increase urinary calcium excretion. 4. Thiazolidinediones (e.g., pioglitazone) \u2014 shift mesenchymal stem cell differentiation toward adipocytes. 5. Anticonvulsants (e.g., phenytoin) \u2014 accelerate vitamin D catabolism via CYP induction. 6. Aromatase inhibitors \u2014 reduce estrogen in postmenopausal women."]','A','Thiazide diuretics INCREASE calcium reabsorption and may have a bone-protective effect — opposite to loop diuretics. Glucocorticoids carry the highest bone loss risk: prednisone ≥5 mg/day for ≥3 months requires bisphosphonate prophylaxis. Identifying these medications in patients'''' drug histories is important in fracture risk assessment.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Osteoporosis Pharmacotherapy','easy','flashcard','When is teriparatide (parathyroid hormone analog) indicated for osteoporosis?','["Teriparatide is reserved for patients at HIGH RISK of fractures and those who have FAILED or CANNOT TOLERATE other osteoporosis therapies (bisphosphonates, denosumab). Specifically indicated for: postmenopausal women and men with severe osteoporosis; multiple fragility fractures; glucocorticoid-induced osteoporosis at high fracture risk. Limited to 2 years maximum use."]','A','Teriparatide''''s anabolic mechanism (building new bone) is uniquely suited to patients with very low bone density and multiple fractures where inhibiting resorption alone is insufficient. After completing the 2-year course, follow-up with an antiresorptive agent is essential to maintain bone density gains achieved.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Muscle Relaxants','easy','flashcard','What is baclofen''''s mechanism of action and for which MSK condition is it most commonly used?','["Baclofen is a GABA-B receptor agonist that acts at the spinal cord level, reducing motor neuron excitability by hyperpolarisation (K+ efflux, Ca2+ influx inhibition). Most commonly used for spasticity in MULTIPLE SCLEROSIS and SPINAL CORD INJURY. It reduces spasm frequency, severity, and muscle tone without affecting voluntary motor control as severely as non-selective CNS depressants."]','A','GABA-B receptors are metabotropic (G-protein coupled), unlike GABA-A (ionotropic/chloride channels targeted by benzodiazepines). Baclofen withdrawal syndrome is serious — abrupt discontinuation causes rebound spasticity, seizures, and hallucinations. For severe spasticity refractory to oral therapy, intrathecal baclofen via implanted pump is an option.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Muscle Relaxants','medium','flashcard','How do centrally acting muscle relaxants (baclofen, diazepam) differ from directly acting ones (dantrolene) in mechanism?','["Centrally acting (spinal cord): Baclofen (GABA-B agonist), diazepam (GABA-A positive allosteric modulator), tizanidine (alpha-2 agonist) \u2014 reduce motor neuron excitability via CNS pathways. Directly acting (peripheral): Dantrolene \u2014 inhibits calcium release from sarcoplasmic reticulum in skeletal muscle, uncoupling excitation-contraction coupling."]','A','Central agents affect the entire CNS and can cause sedation, cognitive impairment, and dependence. Dantrolene acts directly on muscle and avoids CNS sedation, but can cause generalised muscle weakness. Dantrolene is the ONLY agent used for malignant hyperthermia (volatile anaesthetic-triggered SR calcium release). It is also used chronically for cerebral palsy, MS spasticity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Muscle Relaxants','easy','flashcard','Cyclobenzaprine is structurally related to which drug class and what limits its use in elderly patients?','["Cyclobenzaprine is structurally related to tricyclic antidepressants (TCAs). Limits its use in elderly: significant anticholinergic adverse effects (dry mouth, urinary retention, constipation, blurred vision) and sedation. TCAs and anticholinergic agents are on the Beers Criteria list of drugs to avoid in elderly patients due to risk of falls, delirium, and urinary retention."]','A','Cyclobenzaprine is used for SHORT-TERM (≤2-3 weeks) relief of acute musculoskeletal spasm associated with sprains and strains. It has no anti-inflammatory effect. Its cardiac conduction effects (prolonged QT, arrhythmias) mirror those of TCAs and require caution in patients with cardiovascular disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Muscle Relaxants','medium','flashcard','What is tizanidine''''s mechanism and what critical drug interaction must be avoided?','["Tizanidine is a centrally acting alpha-2 adrenergic agonist at the spinal cord level \u2014 reduces excitatory interneuron neurotransmission reducing spasticity. CRITICAL interaction: CIPROFLOXACIN (and fluvoxamine) are potent CYP1A2 inhibitors; since tizanidine is primarily metabolised by CYP1A2, concurrent use causes dramatic (up to 10-fold) increase in tizanidine plasma levels causing severe hypotension, bradycardia, and excessive sedation \u2014 CONTRAINDICATED."]','A','Tizanidine has a short half-life (2.5 hours) so it is dosed 3x/day. It is used for spasticity in MS, ALS, and spinal cord injury. Caution in hepatic impairment. Other CYP1A2 inhibitors (fluvoxamine, antifungals) also increase tizanidine levels. Alpha-2 agonist properties can cause sedation and dry mouth (similar to clonidine).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Muscle Relaxants','hard','flashcard','What is malignant hyperthermia, and how does dantrolene specifically treat it?','["Malignant hyperthermia (MH): a pharmacogenetic disorder (usually RYR1 mutation) triggered by volatile anaesthetics (halothane, sevoflurane) and succinylcholine, causing uncontrolled Ca2+ release from the sarcoplasmic reticulum, leading to rigidity, hyperthermia, metabolic acidosis, rhabdomyolysis, and potentially death. Dantrolene: inhibits RYR1 receptor-mediated Ca2+ release from the SR, reversing the pathological process."]','A','MH is a medical emergency with mortality >10% without treatment. Dantrolene should be readily available in any anaesthetic facility. Treatment: immediately stop triggering agent, give dantrolene IV 2.5 mg/kg bolus (repeat up to 10 mg/kg), cool patient, correct metabolic acidosis. MHAUS (Malignant Hyperthermia Association) provides emergency protocols.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Muscle Relaxants','easy','flashcard','What are the main indications for benzodiazepine-based muscle relaxation (diazepam) in MSK conditions?','["Diazepam for MSK: 1. Acute painful musculoskeletal spasm (back spasm, neck spasm); 2. Spasticity from CNS disorders (MS, cerebral palsy, spinal cord injury); 3. Tetanus-induced muscle rigidity; 4. Pre-procedure muscle relaxation. Limited to short-term use due to dependence risk, sedation, and cognitive impairment."]','A','Benzodiazepines provide muscle relaxation by enhancing GABA-A-mediated presynaptic inhibition in the spinal cord (alpha-2 GABA-A subunit). Diazepam is preferred over other benzodiazepines for muscle spasm due to long half-life and clinical familiarity. Caution in elderly (fall risk, cognitive effects, delirium), respiratory disease, and patients with substance abuse history.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Muscle Relaxants','medium','flashcard','What is the rationale and advantages of intrathecal baclofen delivery for severe spasticity?','["Intrathecal baclofen (ITB): delivered directly into cerebrospinal fluid via implanted pump, achieving drug concentrations at the spinal cord 100x higher than achievable with oral dosing. Advantages: 1. Bypasses blood-brain barrier; 2. Much lower doses needed (reducing systemic side effects); 3. Programmable delivery; 4. Titratable to desired level of spasticity control; 5. Effective for severe MS, SCI, TBI, and CP spasticity."]','A','Oral baclofen''''s dose is limited by side effects (sedation, weakness, dizziness). ITB allows precise dosing targeting the spinal cord. Complications: pump/catheter malfunction (abrupt withdrawal syndrome = seizures, hyperthermia), infection, intrathecal catheter dislodgement. Patients require close monitoring and regular pump refill appointments.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Muscle Relaxants','hard','flashcard','Compare the receptor mechanisms of baclofen, diazepam, and tizanidine as muscle relaxants.','["Baclofen: GABA-B agonist (metabotropic, G-protein coupled) at spinal cord \u2014 reduces K+ conductance hyperpolarisation and reduces Ca2+ influx. Diazepam: GABA-A positive allosteric modulator (increases Cl- channel opening frequency) at spinal cord and brain \u2014 enhances inhibitory tone. Tizanidine: alpha-2 adrenergic agonist at spinal interneurons \u2014 reduces excitatory neurotransmitter (glutamate, substance P) release."]','A','All three act centrally but via distinct mechanisms and receptor systems. Baclofen is the most targeted (spinal GABA-B). Diazepam affects GABA-A throughout the CNS (broader sedation risk). Tizanidine has antispasticity + analgesic properties (reduces substance P). Selection depends on underlying condition, comorbidities, and tolerance of side effects.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Muscle Relaxants','medium','flashcard','What is methocarbamol and how does it differ mechanistically from baclofen?','["Methocarbamol is a centrally acting muscle relaxant that produces general CNS depression, reducing polysynaptic reflexes in the spinal cord and brain. Its precise mechanism is not fully characterised. It differs from baclofen: baclofen is a specific GABA-B receptor agonist with a defined mechanism, while methocarbamol acts as a non-specific CNS depressant without a specific receptor target. Used for short-term relief of acute musculoskeletal spasm."]','A','Methocarbamol does not directly relax skeletal muscle and does not act at the neuromuscular junction. It is available orally and IV. Common adverse effects: sedation, dizziness, nausea. IV formulation uses polyethylene glycol carrier which may cause problems in renal disease. It is not used for spasticity from CNS disorders (unlike baclofen).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Muscle Relaxants','easy','flashcard','What are the key adverse effects of long-term opioid-based analgesia for MSK pain that are NOT seen with muscle relaxants?','["Opioid-specific adverse effects not shared by muscle relaxants: 1. Opioid-induced constipation (OIC) \u2014 persists with tolerance; 2. Respiratory depression; 3. Physical dependence and opioid use disorder; 4. Opioid-induced androgen deficiency (OPIAD) \u2014 reduced testosterone; 5. Hyperalgesia (increased pain sensitivity with long-term use); 6. Immunosuppression. Muscle relaxants primarily cause CNS depression (sedation) and anticholinergic effects (cyclobenzaprine)."]','A','This comparison is clinically important for pain management decisions. Opioids are high-risk for MSK chronic pain due to these adverse effects. Non-pharmacological approaches (physiotherapy, cognitive behavioural therapy, exercise) plus adjuvants (NSAIDs, muscle relaxants, topical agents) should be maximised before long-term opioids.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Local Anaesthetics in MSK','easy','flashcard','What is the mechanism of action of local anaesthetics and which nerve fibres are most sensitive?','["Local anaesthetics block voltage-gated sodium channels, preventing Na+ influx required for action potential propagation. Most sensitive fibres: small unmyelinated C fibres (pain, temperature, autonomic) and small myelinated A-delta fibres. Least sensitive: large myelinated A-alpha (motor) and A-beta (touch, proprioception) fibres \u2014 exploited in epidural anaesthesia."]','A','The differential sensitivity (pain fibres more sensitive than motor fibres) allows analgesia without complete motor paralysis at appropriate concentrations. The ionised form of the local anaesthetic interacts with the sodium channel receptor from inside the membrane, but only the unionised form crosses the lipid membrane.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Local Anaesthetics in MSK','medium','flashcard','Classify local anaesthetics as amides vs esters and describe their different metabolism.','["AMIDES (''''lidocaine amide to remember'''' \u2014 2 ''''i''''s in name: lidocaine, bupivacaine, ropivacaine, mepivacaine, prilocaine): metabolised by LIVER. ESTERS (procaine, tetracaine, cocaine, benzocaine): hydrolysed by PLASMA CHOLINESTERASE (pseudocholinesterase). Para-aminobenzoic acid (PABA) is a metabolite of all esters \u2014 responsible for ester allergic reactions (cross-reactive within the class)."]','A','This classification has clinical implications: patients with pseudocholinesterase deficiency cannot safely metabolise ester local anaesthetics. True allergy to an amide is exceedingly rare; to an ester is rare but more common (via PABA). Allergy to one ester means avoid ALL esters. Allergy to one amide does NOT prevent use of another amide.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Local Anaesthetics in MSK','medium','flashcard','What factors determine the onset and duration of action of local anaesthetics?','["ONSET: primarily determined by pKa (lower pKa = more unionised at pH 7.4 = faster onset) and tissue pH (acidosis in infection = slower onset). DURATION: primarily determined by lipid solubility (higher = longer duration) and protein binding (higher = longer duration). POTENCY: also determined by lipid solubility."]','A','Example: lidocaine (pKa 7.9) has intermediate onset; bupivacaine (pKa 8.1) has slower onset but longer duration due to higher lipid solubility and protein binding. Epinephrine addition prolongs duration of ALL local anaesthetics by causing vasoconstriction, reducing vascular absorption. Adding bicarbonate to local anaesthetic preparation increases pH, shifting equilibrium toward unionised form for faster onset.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Local Anaesthetics in MSK','easy','flashcard','What is local anaesthetic systemic toxicity (LAST) and what is its specific treatment?','["LAST occurs when local anaesthetic reaches toxic systemic blood levels (inadvertent intravascular injection or excessive dose). Manifestations: CNS (perioral numbness, tinnitus, confusion, seizures) then cardiovascular (arrhythmias, cardiac arrest). Specific treatment: 20% INTRAVENOUS LIPID EMULSION (lipid rescue) \u2014 acts as a pharmacokinetic ''''lipid sink'''' sequestering lipophilic local anaesthetic from cardiac tissues. Also manage airway, seizures, and cardiac resuscitation."]','A','Lipid emulsion therapy (intralipid 20%, 1.5 mL/kg bolus then infusion) is specifically for LAST. The lipid phase absorbs the highly lipophilic local anaesthetic (particularly bupivacaine) from cardiac ion channels. Bupivacaine causes particularly severe cardiac toxicity due to high lipid solubility and affinity for sodium and potassium channels. Aspiration before injection is essential to prevent intravascular injection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Local Anaesthetics in MSK','hard','flashcard','Why does lidocaine require epinephrine for certain procedures, and when should epinephrine be AVOIDED?','["Epinephrine addition: causes vasoconstriction (alpha-1 effect), reducing local anaesthetic vascular absorption, prolonging duration (30-100%), reducing systemic toxicity, and reducing bleeding at surgical site. Avoid epinephrine in: ring blocks of fingers, toes, penis, nose (end-arteries \u2014 vasoconstriction causes ischaemia and gangrene), and in patients with severe cardiovascular disease or thyrotoxicosis."]','A','The classic contraindication ''''fingers, toes, nose, and those'''' (with end-arteries) reflects the risk of ischaemic necrosis from vasoconstriction in tissues with limited collateral circulation. However, low-concentration epinephrine (1:200,000) is increasingly considered safe even for digital blocks at low doses — this remains somewhat controversial.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Local Anaesthetics in MSK','medium','flashcard','What is the significance of pseudocholinesterase deficiency for patients receiving local anaesthetics?','["Pseudocholinesterase deficiency: ester local anaesthetics (procaine, tetracaine, cocaine, benzocaine) are hydrolysed by plasma pseudocholinesterase. In deficiency, ester hydrolysis is prolonged, causing drug accumulation and potential toxicity at normal doses. AMIDE local anaesthetics (lidocaine, bupivacaine, ropivacaine) are safely metabolised by the liver and are the preferred choice in pseudocholinesterase deficiency."]','A','Pseudocholinesterase deficiency is also clinically important for succinylcholine (suxamethonium) — a neuromuscular blocker metabolised by plasma cholinesterase. Deficiency causes prolonged paralysis (''''scoline apnoea''''). The deficiency may be inherited (genetic variants) or acquired (liver disease, pregnancy, malnutrition).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Local Anaesthetics in MSK','easy','flashcard','Which local anaesthetic is used as an intravenous antiarrhythmic agent, and what is the clinical relevance?','["Lidocaine is used as a class IB antiarrhythmic drug \u2014 given IV for ventricular arrhythmias (VF, VT). Mechanism: blocks Na+ channels in cardiac conduction system with rapid on-off kinetics. The same Na+ channel blocking mechanism underlies both local anaesthetic and antiarrhythmic effects."]','A','This dual role means that systemic lidocaine toxicity (from regional anaesthesia) can manifest as cardiac arrhythmias — importantly bradycardia and cardiac arrest. Conversely, IV lidocaine is used for acute ventricular arrhythmias in cardiac arrest algorithms. The therapeutic window is narrow; toxic effects occur at plasma levels not much above therapeutic levels.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Local Anaesthetics in MSK','hard','flashcard','Why is the onset of local anaesthetic action delayed or completely prevented in infected tissues?','["Infected tissues have a LOW pH (pH 5.5-6.0) due to bacterial acid production. Local anaesthetics have weak base properties. At low pH, the equilibrium shifts toward the IONISED (protonated, BH+) form. Only the UNIONISED (non-protonated, B) form crosses lipid nerve membranes. With less unionised drug available, fewer molecules penetrate the nerve membrane \u2192 delayed or no onset of anaesthesia."]','A','This is why dentists struggle to anaesthetise acutely infected teeth despite multiple injections. Practical solutions: alkalinisation of local anaesthetic with sodium bicarbonate (raises pH → more unionised form); use of regional nerve block proximal to the infected area (where tissue pH is normal); adequate antibiotic treatment to reduce infection before elective procedures.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Local Anaesthetics in MSK','medium','flashcard','What are the advantages of ropivacaine over bupivacaine for epidural anaesthesia in orthopaedic surgery?','["Ropivacaine vs bupivacaine: Both are amide long-acting local anaesthetics with similar duration. Ropivacaine has: 1. Less cardiac toxicity (lower lipid solubility, slower cardiac Na+ channel binding); 2. Motor-sparing properties at lower concentrations (useful for ambulatory patients); 3. Lower CNS toxicity. Both used for epidural and peripheral nerve blocks in orthopaedic surgery."]','A','Bupivacaine''''s cardiac toxicity (particularly with inadvertent IV injection) can be refractory to resuscitation — the tightly bound drug is slow to dissociate from cardiac sodium channels. Ropivacaine, being the S-enantiomer, has lower cardiac toxicity. Lipid emulsion rescue works for both but is more critically needed for bupivacaine.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Local Anaesthetics in MSK','hard','flashcard','Prilocaine can cause a unique adverse effect not seen with other amide local anaesthetics. What is it?','["Prilocaine can cause METHAEMOGLOBINAEMIA. One of its metabolites (o-toluidine) oxidises haemoglobin Fe2+ to Fe3+, forming methaemoglobin, which cannot carry oxygen. Presents as cyanosis unresponsive to oxygen, pulse oximetry reading of ~85% regardless of true saturation. Treatment: IV methylene blue (1-2 mg/kg) which reduces metHb back to Hb. Contraindicated in infants and those with G6PD deficiency."]','A','Prilocaine is used in EMLA cream (eutectic mixture of lidocaine and prilocaine) for topical anaesthesia. Risk of methaemoglobinaemia from EMLA is low at recommended doses in adults but significant in infants (who have less methaemoglobin reductase). Large amounts of prilocaine IV (as in tumescent liposuction) carry higher risk.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Drug-Induced MSK Conditions','easy','flashcard','Which class of lipid-lowering drugs most commonly causes drug-induced myopathy, and what is the most severe manifestation?','["Statins (HMG CoA reductase inhibitors) most commonly cause drug-induced myopathy. Spectrum: myalgia (muscle pain, no CK rise) \u2192 myopathy (muscle symptoms + elevated CK) \u2192 rhabdomyolysis (severe muscle breakdown + markedly elevated CK + myoglobinuria + AKI). Rhabdomyolysis is rare but potentially fatal. Symptoms typically resolve with drug discontinuation."]','A','Risk factors for statin myopathy: high statin dose, female sex, advanced age, hypothyroidism, vitamin D deficiency, renal insufficiency, CYP3A4 inhibitors (for statins metabolised by CYP3A4 — simvastatin, lovastatin, atorvastatin). Genetic factors: SLCO1B1 polymorphism affects hepatic statin uptake and predisposes to myopathy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Drug-Induced MSK Conditions','medium','flashcard','Which drug interactions significantly increase the risk of statin-induced rhabdomyolysis?','["High-risk interactions: 1. CYP3A4 inhibitors with CYP3A4-metabolised statins (simvastatin, lovastatin, atorvastatin) \u2014 azole antifungals, HIV protease inhibitors, clarithromycin, cyclosporine, amiodarone, diltiazem, verapamil. 2. Gemfibrozil (OATP1B1 inhibitor) with ANY statin. 3. Niacin. 4. Colchicine (mitochondrial toxicity). Pravastatin and rosuvastatin are NOT metabolised by CYP3A4 and carry lower interaction risk."]','A','The highest risk combination is simvastatin + strong CYP3A4 inhibitor (e.g., itraconazole). FDA has issued dose limits for simvastatin when used with specific interacting drugs. Gemfibrozil is a particularly dangerous combination — it inhibits statin glucuronidation AND OATP1B1-mediated hepatic uptake — avoid this combination. Fenofibrate (unlike gemfibrozil) does not carry the same interaction risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Drug-Induced MSK Conditions','easy','flashcard','What are the black box warnings associated with fluoroquinolone antibiotics relevant to MSK?','["Fluoroquinolone black box warnings: 1. Tendinitis and tendon rupture (Achilles tendon most commonly); 2. Peripheral neuropathy (can be permanent); 3. Central nervous system effects (hallucinations, anxiety, insomnia, confusion, seizures). Risk of tendon injury increased in patients >60 years, on corticosteroids, with kidney/heart/lung transplants."]','A','Fluoroquinolones inhibit topoisomerase II and IV — in bacteria, this kills the organism, but at therapeutic concentrations, human topoisomerases are also affected, potentially explaining tendon toxicity. The exact mechanism of tendon damage may involve impaired collagen synthesis, mitochondrial toxicity in tendon cells, and reactive oxygen species generation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Drug-Induced MSK Conditions','hard','flashcard','What is the genetic marker for severe allopurinol hypersensitivity and which populations require screening?','["HLA-B*5801 allele is strongly associated with allopurinol hypersensitivity syndrome (AHS) \u2014 Stevens-Johnson syndrome (SJS) and toxic epidermal necrolysis (TEN). High-risk populations: Han Chinese (HLA-B*5801 frequency ~6-8%), Thai (8-9%), Korean (12%), South Asian populations. Patients with chronic kidney disease (reduced allopurinol clearance) have higher risk regardless of HLA status. Screening for HLA-B*5801 recommended before allopurinol initiation in high-risk Asian populations."]','A','AHS usually occurs within the first 8 weeks of allopurinol therapy and is more common at higher initial doses. Current guidelines recommend starting allopurinol at the lowest possible dose (100 mg/day) and titrating slowly. The risk correlates with renal function — patients with eGFR <60 mL/min have higher risk of AHS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Drug-Induced MSK Conditions','medium','flashcard','What is glucocorticoid-induced osteonecrosis (avascular necrosis), and what is the most common site?','["Glucocorticoid-induced osteonecrosis (avascular necrosis/AVN): ischaemic death of bone due to disruption of blood supply from: fat embolism (steroids increase lipid droplets in sinusoids), increased intraosseous pressure, impaired vascular repair. Most common site: femoral head. Other sites: humeral head, knee condyles, talar dome. Presents as joint pain (especially with weight-bearing), night pain, and limited ROM."]','A','AVN risk correlates with corticosteroid dose and duration. High-dose pulses (e.g., >40 mg prednisolone/day) or cumulative high doses carry greatest risk. MRI is the gold standard for early diagnosis (before X-ray changes). Treatment: depends on stage — conservative (protected weight bearing) for early stages; core decompression, bone grafting, or joint replacement for advanced disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Drug-Induced MSK Conditions','medium','flashcard','How do fluoroquinolones damage tendons at the cellular level?','["Fluoroquinolone tendon toxicity mechanisms: 1. Impaired collagen synthesis in tenocytes (matrix metalloproteinase upregulation); 2. Mitochondrial toxicity (inhibit mitochondrial DNA gyrase); 3. Reactive oxygen species (ROS) generation in tenocytes; 4. Magnesium chelation (fluoroquinolones chelate Mg2+, impairing tendon cell function). The Achilles tendon has relatively poor blood supply, increasing vulnerability."]','A','Tendon rupture typically occurs within the first month of therapy but can occur up to several months after discontinuation. The injury likely begins as tenocyte apoptosis and collagen degradation, weakening the tendon before clinical rupture. Risk is dramatically increased by concurrent corticosteroid use (also impairs collagen synthesis).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Drug-Induced MSK Conditions','hard','flashcard','What is immune-mediated necrotising myopathy (IMNM) and how does it differ from typical statin myopathy?','["IMNM is a rare, severe autoimmune muscle disease triggered by statins. Unlike typical statin myopathy (which resolves with drug discontinuation), IMNM PERSISTS or worsens after stopping statins. Characterised by: markedly elevated CK (often >10,000 IU/L), proximal muscle weakness, anti-HMGCR antibodies (anti-3-hydroxy-3-methylglutaryl CoA reductase antibodies). Requires IMMUNOSUPPRESSIVE THERAPY (steroids \u00b1 azathioprine/IVIG)."]','A','IMNM represents a mechanistic shift: statins expose the HMGCR enzyme in regenerating muscle fibres, triggering antibody formation. Antibody-mediated muscle fibre destruction continues even without the statin trigger. Distinguishing IMNM from typical statin myopathy is critical because IMNM requires ongoing immunosuppression, not just drug cessation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Drug-Induced MSK Conditions','easy','flashcard','Bisphosphonates can cause osteonecrosis of the jaw (ONJ). What clinical recommendations reduce this risk?','["Risk reduction strategies: 1. Complete all necessary dental procedures BEFORE starting bisphosphonates; 2. Maintain good oral hygiene throughout treatment; 3. Avoid invasive dental procedures (extractions, implants) during high-intensity bisphosphonate therapy if possible; 4. Consider drug holiday before elective invasive dental surgery (evidence limited); 5. Higher risk with IV bisphosphonates (cancer patients) than oral osteoporosis doses."]','A','ONJ risk with oral bisphosphonates for osteoporosis is very low (~0.01-0.04%) compared to IV bisphosphonates in cancer patients (~0.7-6.7%). Most ONJ cases involve dental extraction trauma. Informing dentists of bisphosphonate use is important. Conservative dental management (non-surgical) is preferred when possible during bisphosphonate therapy.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Drug-Induced MSK Conditions','medium','flashcard','Colchicine can cause myopathy with long-term use. Which drug interactions significantly increase this risk?','["Colchicine myopathy risk is increased by: 1. CYP3A4 inhibitors (clarithromycin, itraconazole, cyclosporine, verapamil, amiodarone) \u2014 increase colchicine plasma levels. 2. P-gp inhibitors (cyclosporine, verapamil, amiodarone) \u2014 further increase levels. 3. STATINS \u2014 combined statin + colchicine increases myopathy risk (additive mitochondrial toxicity). Dose reduction required with CYP3A4/P-gp inhibitors; avoid use in severe renal or hepatic impairment."]','A','Colchicine is both a CYP3A4 and P-glycoprotein substrate. The case of colchicine toxicity (myopathy, pancytopenia, multi-organ failure) in patients on cyclosporine is well-documented. Clarithromycin is a particularly dangerous combination that has caused colchicine fatalities due to dramatically increased plasma levels.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Musculoskeletal System','Pharmacology','Drug-Induced MSK Conditions','hard','flashcard','What is the mechanism of tetracycline-induced adverse effects on bone, and how does this compare to fluoroquinolone effects on developing cartilage?','["Tetracyclines: chelate calcium (and other divalent cations) and are incorporated into growing bone and teeth. They inhibit bone mineralisation and cause permanent staining of developing teeth and bones in children exposed in utero or under 8 years old. Fluoroquinolones: damage growing cartilage (arthropathy) in paediatric patients \u2014 exact mechanism involves topoisomerase inhibition, mitochondrial toxicity, and reactive oxygen species in chondrocytes. Both agents are avoided/limited in children."]','A','Tetracycline deposition in bone is used clinically — double tetracycline labelling is used to measure bone turnover rate in bone biopsies (two courses of tetracycline given weeks apart show fluorescent bands under UV microscopy). The contraindication of tetracyclines in children <8 years is absolute due to tooth/bone effects. Fluoroquinolones in children are restricted to specific clinical scenarios (e.g., cystic fibrosis).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
